Spec: docs/requirements.md. Every failure raises ValidationError(code, message).
"""

import re
import unicodedata
from dataclasses import dataclass
from datetime import date, datetime, timezone

MAX_DEPTH = 6
PAN_MIN_LEN = 13
PAN_MAX_LEN = 19
EXPIRY_MAX_YEARS_AHEAD = 10
METADATA_MAX_KEYS = 20
METADATA_MAX_VALUE_LEN = 256
POLICY_MODES = frozenset({"single_use", "multi_use", "network"})

_EXPIRY_RE = re.compile(r"(0[1-9]|1[0-2])/(\d{4})")


class ValidationError(Exception):
    def __init__(self, code, message):
        super().__init__(f"{code}: {message}")
        self.code = code
        self.message = message


@dataclass(frozen=True)
class ValidationResult:
    ok: bool = True


def validate_tokenization_request(req, now=None):
    """Validate a tokenization request. Returns ValidationResult(ok=True) or raises."""
    today = (now or datetime.now(timezone.utc)).date()

    req = _normalize(req, depth=1, path="$")  # NFC, null-byte and depth checks
    if not isinstance(req, dict):
        raise ValidationError("ERR_TYPE", "request must be an object")

    request_id = req.get("request_id")
    if not isinstance(request_id, str) or not request_id:
        raise ValidationError("ERR_MISSING_FIELD", "request_id is required")

    card = req.get("card")
    if not isinstance(card, dict):
        raise ValidationError("ERR_MISSING_FIELD", "card is required")

    _check_pan(card.get("pan"))
    _check_expiry(card.get("expiry"), today)

    if req.get("persist") is True and _present(card.get("cvv")):
        raise ValidationError("ERR_CVV_STORED", "cvv must not be stored")

    if _present(req.get("metadata")):
        _check_metadata(req["metadata"])

    if _present(req.get("token_policy")):
        _check_token_policy(req["token_policy"])

    return ValidationResult(ok=True)


def _present(value):
    """Optional fields: None and empty string count as missing."""
    return value is not None and value != ""


def _normalize(value, depth, path):
    """Return a copy with NFC-normalized strings; reject null bytes and excess depth."""
    if isinstance(value, dict):
        _check_depth(depth, path)
        return {
            _normalize_str(k, f"{path} key"): _normalize(v, depth + 1, f"{path}.{k}")
            for k, v in value.items()
        }
    if isinstance(value, list):
        _check_depth(depth, path)
        return [_normalize(v, depth + 1, f"{path}[{i}]") for i, v in enumerate(value)]
    if isinstance(value, str):
        return _normalize_str(value, path)
    return value


def _check_depth(depth, path):
    if depth > MAX_DEPTH:
        raise ValidationError("ERR_DEPTH", f"nesting exceeds {MAX_DEPTH} at {path}")


def _normalize_str(s, path):
    if "\x00" in s:
        raise ValidationError("ERR_NULL_BYTE", f"null byte in {path}")
    return unicodedata.normalize("NFC", s)


def _check_pan(pan):
    if not isinstance(pan, str) or pan == "":
        raise ValidationError("ERR_MISSING_FIELD", "card.pan is required")
    digits = pan.replace(" ", "")
    if not (digits.isascii() and digits.isdigit()):
        raise ValidationError("ERR_CARD_FORMAT", "card.pan must contain only digits and spaces")
    if not PAN_MIN_LEN <= len(digits) <= PAN_MAX_LEN:
        raise ValidationError("ERR_PAN_LENGTH", f"card.pan must be {PAN_MIN_LEN}-{PAN_MAX_LEN} digits")
    if not _luhn_ok(digits):
        raise ValidationError("ERR_PAN_LUHN", "card.pan failed Luhn check")


def _luhn_ok(digits):
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0


def _check_expiry(expiry, today):
    m = _EXPIRY_RE.fullmatch(expiry) if isinstance(expiry, str) else None
    if m is None:
        raise ValidationError("ERR_EXPIRY_RANGE", "card.expiry must be MM/YYYY")
    month, year = int(m.group(1)), int(m.group(2))
    if (year, month) < (today.year, today.month):
        raise ValidationError("ERR_EXPIRY_PAST", "card.expiry is in the past")
    if (year, month) > (today.year + EXPIRY_MAX_YEARS_AHEAD, today.month):
        raise ValidationError("ERR_EXPIRY_RANGE", f"card.expiry more than {EXPIRY_MAX_YEARS_AHEAD} years ahead")


def _check_metadata(metadata):
    if not isinstance(metadata, dict):
        raise ValidationError("ERR_TYPE", "metadata must be an object")
    if len(metadata) > METADATA_MAX_KEYS:
        raise ValidationError("ERR_METADATA_SIZE", f"metadata has more than {METADATA_MAX_KEYS} keys")
    for key, value in metadata.items():
        if not isinstance(value, str):
            raise ValidationError("ERR_TYPE", f"metadata.{key} must be a string")
        if len(value) > METADATA_MAX_VALUE_LEN:
            raise ValidationError("ERR_METADATA_SIZE", f"metadata.{key} exceeds {METADATA_MAX_VALUE_LEN} chars")


def _check_token_policy(policy):
    if not isinstance(policy, dict):
        raise ValidationError("ERR_TYPE", "token_policy must be an object")
    if policy.get("mode") not in POLICY_MODES:
        raise ValidationError("ERR_POLICY_MODE", f"token_policy.mode must be one of {sorted(POLICY_MODES)}")
